import numpy as np
import matplotlib.pyplot as plt
from scipy.signal import savgol_filter
import scipy.interpolate as interp
plt.ion()

sumprof = np.load('./moor_npy/oc_prof_sum_u.npy')
depth = np.load('./moor_npy/oc_prof_dep_7_55.npy')

sumavg = np.nanmean(sumprof,axis=0)
sumavgsmooth = savgol_filter(sumavg,11,3)

plt.plot(sumavg,depth,linestyle='--')
plt.plot(sumavgsmooth,depth)
plt.gca().invert_yaxis()

f = interp.interp1d(depth,sumavgsmooth,fill_value='extrapolate')

